<div class="page-head"><div><span class="eyebrow">INVENTAIRE</span><h1>Mouvements de stock</h1><p class="muted">Enregistrez les entrées, sorties et corrections d'inventaire.</p></div></div><div class="panel"><h2>Ajuster un stock</h2><form class="form-grid" method="post" action="<?= e(url('/stock/adjust')) ?>"><input type="hidden" name="_csrf" value="<?= csrf() ?>"><label>Produit<select name="product_id" required><?php foreach($products as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['name']) ?> — <?= (int)$p['stock'] ?> en stock</option><?php endforeach; ?></select></label><label>Variation (+ entrée / - sortie)<input type="number" name="delta" required min="-100000" max="100000" placeholder="Ex. 15 ou -3"></label><label>Motif<input name="reason" required maxlength="190" placeholder="Réception fournisseur, casse..."></label><div class="form-actions"><button class="btn primary">Valider le mouvement</button></div></form></div><div class="panel"><h2>Historique récent</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Produit</th><th>Type</th><th>Quantité</th><th>Motif</th><th>Utilisateur</th></tr></thead><tbody><?php foreach($rows as $m): ?><tr><td><?= e($m['created_at']) ?></td><td><?= e($m['product']) ?></td><td><?= e($m['type']) ?></td><td><?= (int)$m['quantity'] ?></td><td><?= e($m['reason']) ?></td><td><?= e($m['user_name']??'—') ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">Aucun mouvement enregistré.</td></tr><?php endif; ?></tbody></table></div></div>